<?php $title='Nilai Saya';$page='grades';$pdo=Database::connection();$q=$pdo->prepare('SELECT t.title task_title,m.title module_title,s.score,s.feedback,s.graded_at FROM submissions s JOIN tasks t ON t.id=s.task_id JOIN modules m ON m.id=t.module_id WHERE s.student_id=? ORDER BY s.submitted_at DESC');$q->execute([current_user()['id']]);$rows=$q->fetchAll();require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><h1>Nilai Saya</h1><p>Riwayat hasil penilaian tugas dan umpan balik guru.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Tugas</th><th>Modul</th><th>Nilai</th><th>Umpan Balik Guru</th><th>Tanggal Dinilai</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['task_title']) ?></td><td><?= e($r['module_title']) ?></td><td><?= $r['score']===null?'<span class="badge warning">Menunggu</span>':'<b>'.e($r['score']).'</b>' ?></td><td><?= e($r['feedback']??'—') ?></td><td><?= e(format_date($r['graded_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$rows): ?><div class="empty-state">Belum ada riwayat pengumpulan tugas.</div><?php endif; ?></section><?php require __DIR__.'/../_dashboard_end.php'; ?>